using MediatR;using Namaa.Application.Abstractions.Authentication;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Common.Errors;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.Invoices.Commands.CreateInvoice;public sealed class CreateInvoiceCommandHandler(IInvoiceRepository repository,IUserRepository users,ICurrentUser currentUser,IApplicationDbContext db):IRequestHandler<CreateInvoiceCommand,Result<InvoiceDto>>{public async Task<Result<InvoiceDto>>Handle(CreateInvoiceCommand request,CancellationToken cancellationToken){if(!currentUser.IsAuthenticated||currentUser.UserId is not long actorUserId)return Result.Failure<InvoiceDto>(ApplicationErrors.Unauthenticated);if(await repository.ExistsByNumberAsync(request.InvoiceNumber,cancellationToken))return Result.Failure<InvoiceDto>(InvoiceErrors.DuplicateNumber);if(!await users.ExistsByIdAsync(actorUserId,cancellationToken))return Result.Failure<InvoiceDto>(new Error("Invoices.UserNotFound","The user was not found.",ErrorType.NotFound));var e=Invoice.Create(request.InvoiceNumber,request.IssueDate,actorUserId,request.DueDate,request.ProjectId,request.CustomerId,request.Notes);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(InvoiceDto.FromEntity(e));}}
